CREATE SCHEMA checkpoints;
CREATE SCHEMA runner;
CREATE TABLE users (id uuid PRIMARY KEY, display_name text NOT NULL);
CREATE TABLE workspaces (id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE memberships (workspace_id uuid REFERENCES workspaces(id), user_id uuid REFERENCES users(id), role text NOT NULL, PRIMARY KEY(workspace_id,user_id));
CREATE TABLE repositories (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, fixture text NOT NULL, UNIQUE(workspace_id,fixture), UNIQUE(workspace_id,id));
CREATE TABLE snapshots (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, repository_id uuid NOT NULL, commit_sha text NOT NULL, manifest jsonb NOT NULL, FOREIGN KEY(workspace_id,repository_id) REFERENCES repositories(workspace_id,id), UNIQUE(repository_id,commit_sha), UNIQUE(workspace_id,id));
CREATE TABLE runs (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), snapshot_id uuid NOT NULL, fixture text NOT NULL, title text NOT NULL, description text NOT NULL, status text NOT NULL DEFAULT 'queued', outcome text, graph_version text NOT NULL DEFAULT '1', version int NOT NULL DEFAULT 0, fence bigint NOT NULL DEFAULT 0, lease_owner uuid, lease_until timestamptz, cancel_requested boolean NOT NULL DEFAULT false, latest_sequence bigint NOT NULL DEFAULT 0, pending_intent uuid, patch text, patch_sha256 text, evidence jsonb NOT NULL DEFAULT '[]', configuration jsonb NOT NULL, error text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,snapshot_id) REFERENCES snapshots(workspace_id,id), UNIQUE(workspace_id,id));
CREATE INDEX runs_scope ON runs(workspace_id,created_at);
CREATE INDEX runs_recovery ON runs(status,lease_until);
CREATE TABLE run_events (run_id uuid REFERENCES runs(id), sequence bigint, type text NOT NULL, schema_version int NOT NULL DEFAULT 1, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(run_id,sequence));
CREATE TABLE idempotency_keys (workspace_id uuid REFERENCES workspaces(id), actor_id uuid REFERENCES users(id), action text, key text, body_hash text NOT NULL, result_id uuid NOT NULL, PRIMARY KEY(workspace_id,actor_id,action,key));
CREATE TABLE outbox (id uuid PRIMARY KEY, run_id uuid REFERENCES runs(id), type text NOT NULL, dedupe_key text UNIQUE NOT NULL, payload jsonb NOT NULL, published_at timestamptz, attempts int NOT NULL DEFAULT 0, completed_at timestamptz, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE command_receipts (command_id uuid PRIMARY KEY REFERENCES outbox(id), owner uuid NOT NULL, lease_until timestamptz NOT NULL, completed_at timestamptz);
CREATE TABLE execution_intents (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, run_id uuid NOT NULL, logical_step text NOT NULL, input_hash text NOT NULL, request jsonb NOT NULL, required_checkpoint_id text, graph_version text NOT NULL, dispatchable boolean NOT NULL DEFAULT false, result jsonb, consumed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id), UNIQUE(run_id,logical_step));
CREATE TABLE artifacts (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), run_id uuid, object_key text NOT NULL, sha256 text NOT NULL, size bigint NOT NULL, FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id));
CREATE TABLE approvals (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, run_id uuid NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), patch_sha256 text NOT NULL, base_sha text NOT NULL, destination text NOT NULL, decision text NOT NULL, UNIQUE(run_id,patch_sha256,destination), FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id));
CREATE TABLE capacity_reservations (execution_id uuid PRIMARY KEY, owner uuid NOT NULL, lease_until timestamptz NOT NULL);
CREATE TABLE service_leases (name text PRIMARY KEY, owner uuid, lease_until timestamptz NOT NULL);
CREATE TABLE runner.jobs (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, run_id uuid NOT NULL, input_hash text NOT NULL, request jsonb NOT NULL, status text NOT NULL DEFAULT 'queued', result jsonb, cancel_requested boolean NOT NULL DEFAULT false, owner uuid, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now());
